<?php
/**
 * CampusFR Avent C2.2c.6: paid Native course lifecycle in PHPUnit database only.
 * A paid payment attempt is simulated in the test DB: NO external provider call.
 * Every fixture is generated by advanced_testcase and rolled back afterward.
 * @coversNothing
 */
declare(strict_types=1);
namespace local_campusreader;
defined('MOODLE_INTERNAL') || die();

use local_subscriptions\commerce\catalog\domain\CommerceProduct;
use local_subscriptions\commerce\catalog\domain\CommerceProductPrice;
use local_subscriptions\commerce\catalog\domain\CommerceProductStatus;
use local_subscriptions\commerce\catalog\domain\CommerceProductType;
use local_subscriptions\commerce\catalog\domain\CommerceProductEntitlementDefinition;
use local_subscriptions\commerce\catalog\service\CommerceCatalogFactory;
use local_subscriptions\commerce\domain\value\CommerceMoney;
use local_subscriptions\commerce\domain\CommerceItem;
use local_subscriptions\commerce\domain\CommercePurchaseStatus;
use local_subscriptions\commerce\fulfillment\native\checkout\CommerceNativePaidPurchaseCompleter;
use local_subscriptions\commerce\mail\CommerceMailAuditCopyPolicy;
use local_subscriptions\commerce\mail\CommerceMailRuntime;
use local_subscriptions\commerce\mail\context\CommercePurchaseMailContextFactory;
use local_subscriptions\commerce\mail\service\CommerceTransactionalPurchaseMailService;
use local_subscriptions\commerce\payment\attempt\CommercePaymentAttemptStatus;
use local_subscriptions\commerce\payment\repository\CommercePaymentRepository;
use local_subscriptions\commerce\persistence\CommercePersistenceSchema;
use local_subscriptions\commerce\purchase\revocation\CommercePurchaseRightsRevocationService;
use local_subscriptions\payment\dto\InternalEvent;

final class native_paid_cycle_test extends \advanced_testcase {
    /** Confirmed payment creates exactly one lifetime grant and Moodle enrolment; replay is harmless. */
    public function test_paid_event_fulfills_once_and_replay_does_not_duplicate(): void {
        global $DB;
        $this->resetAfterTest(true);
        [$course, $user, $purchaseid, $reference, $payments, $event] = $this->fixture();
        $completer = $this->completer($payments);
        self::assertFalse(is_enrolled(\context_course::instance((int)$course->id), (int)$user->id, '', true));
        $completer->complete($event);
        self::assertSame(CommercePurchaseStatus::FULFILLED,
            $DB->get_field(CommercePersistenceSchema::TABLE_PURCHASE, 'status', ['id' => $purchaseid]));
        $grants = array_values($DB->get_records('local_subs_commerce_grant', ['purchasereference' => $reference]));
        self::assertCount(1, $grants);
        self::assertSame('active', $grants[0]->status);
        self::assertSame('course:' . $course->id . ':full', $grants[0]->resourcekey);
        self::assertNull($grants[0]->validuntil);
        self::assertTrue(is_enrolled(\context_course::instance((int)$course->id), (int)$user->id, '', true));
        self::assertSame(1, $this->enrol_count((int)$course->id, (int)$user->id));
        $completer->complete($event);
        self::assertSame(1, $DB->count_records('local_subs_commerce_grant', ['purchasereference' => $reference]));
        self::assertSame(1, $DB->count_records('local_subs_commerce_ful_attempt', [
            'grantreference' => $grants[0]->grantreference,
        ]));
        self::assertSame(1, $this->enrol_count((int)$course->id, (int)$user->id));
    }

    /** After confirmed fulfillment, purchase revocation removes its own course right. */
    public function test_purchase_revoke_removes_course_access_and_is_idempotent(): void {
        global $DB;
        $this->resetAfterTest(true);
        [$course, $user, , $reference, $payments, $event] = $this->fixture();
        $this->completer($payments)->complete($event);
        $revoker = CommercePurchaseRightsRevocationService::create($DB);
        $result = $revoker->revoke($reference, (int)get_admin()->id, 'C2.2c.6 PHPUnit');
        self::assertSame(1, $result['revoked']);
        self::assertSame(1, $result['course']);
        self::assertSame(0, $this->enrol_count((int)$course->id, (int)$user->id));
        self::assertFalse(is_enrolled(\context_course::instance((int)$course->id), (int)$user->id, '', true));
        self::assertSame('revoked', $DB->get_field('local_subs_commerce_grant', 'status', [
            'purchasereference' => $reference,
        ]));
        self::assertSame(0, $revoker->revoke($reference, (int)get_admin()->id, 'QA replay')['revoked']);
    }

    /** Another independent manual Moodle enrolment must survive revoking this purchase. */
    public function test_purchase_revoke_preserves_preexisting_enrolment(): void {
        global $DB;
        $this->resetAfterTest(true);
        [$course, $user, , $reference, $payments, $event] = $this->fixture();
        $this->getDataGenerator()->enrol_user((int)$user->id, (int)$course->id, 'student', 'manual');
        self::assertTrue(is_enrolled(\context_course::instance((int)$course->id), (int)$user->id, '', true));
        $this->completer($payments)->complete($event);
        $result = CommercePurchaseRightsRevocationService::create($DB)->revoke(
            $reference, (int)get_admin()->id, 'C2.2c.6 preserve independent enrolment'
        );
        self::assertSame(1, $result['revoked']);
        self::assertSame(1, $result['preservedcourse']);
        self::assertTrue(is_enrolled(\context_course::instance((int)$course->id), (int)$user->id, '', true));
        self::assertSame(1, $this->enrol_count((int)$course->id, (int)$user->id));
    }

    /**
     * Fully isolated catalogue/product/purchase/payment fixtures.
     * @return array{0:object,1:object,2:int,3:string,4:CommercePaymentRepository,5:InternalEvent}
     */
    private function fixture(): array {
        global $DB;
        $course = $this->getDataGenerator()->create_course();
        $user = $this->getDataGenerator()->create_user();
        $suffix = strtoupper(bin2hex(random_bytes(7)));
        $sku = 'QA.AVENT.C22C6.' . $suffix;
        $reference = 'qa-c22c6-' . strtolower($suffix);
        $uuid = bin2hex(random_bytes(16));
        $catalogue = (new CommerceCatalogFactory($DB))->admin();
        $catalogue->save_product(new CommerceProduct(
            $sku, CommerceProductType::COURSE_ACCESS, CommerceProductStatus::ACTIVE, 'CFR QA Native paid course'
        ));
        $price = $catalogue->set_price(new CommerceProductPrice(
            $sku, CommerceMoney::from_minor(199, 'EUR')
        ));
        $catalogue->replace_definition($sku, [], [new CommerceProductEntitlementDefinition(
            $sku, 'course_access', 'course:' . $course->id . ':full', null, 1,
            ['courseid' => (int)$course->id, 'roleshortname' => 'student']
        )]);
        $now = time();
        $purchaseid = (int)$DB->insert_record(CommercePersistenceSchema::TABLE_PURCHASE, (object)[
            'purchaseuuid' => $uuid,
            'reference' => $reference,
            'type' => CommerceItem::TYPE_SERVICE,
            'legacyfamily' => null,
            'legacyid' => null,
            'userid' => (int)$user->id,
            'customeremail' => (string)$user->email,
            'status' => CommercePurchaseStatus::PAYMENT_PENDING,
            'currency' => 'EUR',
            'subtotalminor' => 199,
            'discountminor' => 0,
            'totalminor' => 199,
            'customerjson' => json_encode(['firstname' => $user->firstname, 'lastname' => $user->lastname], JSON_THROW_ON_ERROR),
            'snapshotjson' => '{}',
            'metadatajson' => '{}',
            'snapshotversion' => 1,
            'timecreated' => $now,
            'timemodified' => $now,
        ]);
        $DB->insert_record(CommercePersistenceSchema::TABLE_ITEM, (object)[
            'purchaseid' => $purchaseid,
            'position' => 0,
            'itemtype' => CommerceItem::TYPE_SERVICE,
            'itemreference' => $sku,
            'label' => 'CFR QA Native paid course',
            'quantity' => 1,
            'currency' => 'EUR',
            'unitminor' => 199,
            'grossminor' => 199,
            'discountminor' => 0,
            'netminor' => 199,
            'pricingjson' => '{}',
            'fulfillmentjson' => json_encode(['priceid' => $price->get_id()], JSON_THROW_ON_ERROR),
            'metadatajson' => json_encode(['priceid' => $price->get_id(), 'catalogue_type' => CommerceProductType::COURSE_ACCESS], JSON_THROW_ON_ERROR),
        ]);
        $payments = new CommercePaymentRepository($DB);
        $attempt = $payments->create($uuid, 'stripe', 199, 'EUR');
        $attempt = $payments->update_status((int)$attempt->get_id(), CommercePaymentAttemptStatus::PAID,
            'pi_c22c6_' . strtolower($suffix), null, $now);
        $event = new InternalEvent('checkout_completed', ['meta' => [
            'provider' => 'stripe',
            'commerce_payment_id' => (string)$attempt->get_id(),
            'commerce_purchase_uuid' => $uuid,
        ]]);
        return [$course, $user, $purchaseid, $reference, $payments, $event];
    }

    /** Queue messages in the isolated test DB, never dispatch real emails. */
    private function completer(CommercePaymentRepository $payments): CommerceNativePaidPurchaseCompleter {
        global $DB;
        $mail = new CommerceTransactionalPurchaseMailService(
            CommercePurchaseMailContextFactory::create(),
            CommerceMailRuntime::queue_service(),
            null,
            new CommerceMailAuditCopyPolicy()
        );
        return new CommerceNativePaidPurchaseCompleter($DB, $payments, $mail);
    }

    private function enrol_count(int $courseid, int $userid): int {
        global $DB;
        return (int)$DB->count_records_sql(
            'SELECT COUNT(1) FROM {user_enrolments} ue JOIN {enrol} e ON e.id=ue.enrolid'
            . ' WHERE e.courseid=? AND ue.userid=?', [$courseid, $userid]
        );
    }
}
